SELECT p.payment_order_id AS paymentOrderId, p.order_no AS orderNo, p.customer_name AS customerName, CONCAT('¥', FORMAT(p.amount, 2)) AS amount, pr.pay_scene AS payScene, , p.payment_method AS paymentMethod, p.channel_code AS channel, p.channel_transaction_no AS channelTransactionNo, p.status, p.status_type AS statusType, pa.attempt_status AS latestAttemptStatus, pa.attempt_status_type AS latestAttemptStatusType, DATE_FORMAT(pa.completed_at, '%Y-%m-%d %H:%i:%s') AS latestAttemptCompletedAt, DATE_FORMAT(p.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt,
FROM t_payment_order p LEFT JOIN t_prepay_order pr ON pr.id = ( SELECT latest_pr.id FROM t_prepay_order latest_pr WHERE latest_pr.payment_order_id = p.payment_order_id AND CHAR_LENGTH(latest_pr.payment_order_id) = CHAR_LENGTH(p.payment_order_id) AND CAST(latest_pr.payment_order_id AS BINARY(256)) = CAST(p.payment_order_id AS BINARY(256)) AND (SELECT COUNT(*) FROM t_prepay_order all_prepay WHERE all_prepay.payment_order_id = p.payment_order_id AND CHAR_LENGTH(all_prepay.payment_order_id) = CHAR_LENGTH(p.payment_order_id) AND CAST(all_prepay.payment_order_id AS BINARY(256)) = CAST(p.payment_order_id AS BINARY(256))) = 1 ORDER BY latest_pr.created_at DESC, latest_pr.id DESC LIMIT 1 ) LEFT JOIN t_payment_attempt pa ON pa.id = ( SELECT latest_pa.id FROM t_payment_attempt latest_pa WHERE latest_pa.payment_order_id = p.payment_order_id AND CHAR_LENGTH(latest_pa.payment_order_id) = CHAR_LENGTH(p.payment_order_id) AND CAST(latest_pa.payment_order_id AS BINARY(256)) = CAST(p.payment_order_id AS BINARY(256)) ORDER BY latest_pa.created_at DESC, latest_pa.id DESC LIMIT 1 )
p.payment_order_id LIKE CONCAT('%', #{query.paymentOrderId}, '%')
AND p.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND p.channel_code = #{query.channelCode}
AND p.payment_method = #{query.paymentMethod}
AND
AND p.status = 'SUCCESS' AND p.success_at IS NULL
AND p.status IN ('PREPAY_CREATED', 'WAIT_CALLBACK', 'RISK_REVIEW')
AND p.status = #{query.status}
LIMIT #{query.limit} OFFSET #{query.offset}

