UPDATE t_order
SET paid_amount = #{paidAmount},
    order_status = #{orderStatus},
    order_status_type = #{orderStatusType}
WHERE order_no = #{orderNo}
  AND CHAR_LENGTH(order_no) = CHAR_LENGTH(#{orderNo})
  AND CAST(order_no AS BINARY(256)) = CAST(#{orderNo} AS BINARY(256))
  AND order_amount = #{paidAmount}
  AND paid_amount = #{expectedPaidAmount}
  AND customer_name = #{expectedCustomerName}

UPDATE t_bill
SET paid_amount = #{paidAmount},
    bill_status = #{billStatus},
    bill_status_type = #{billStatusType}
WHERE bill_no = #{billNo}
  AND CHAR_LENGTH(bill_no) = CHAR_LENGTH(#{billNo})
  AND CAST(bill_no AS BINARY(256)) = CAST(#{billNo} AS BINARY(256))
  AND order_no = #{orderNo}
  AND CHAR_LENGTH(order_no) = CHAR_LENGTH(#{orderNo})
  AND CAST(order_no AS BINARY(256)) = CAST(#{orderNo} AS BINARY(256))
  AND customer_name = #{customerName}
  AND bill_amount = #{paidAmount}
  AND paid_amount = #{expectedPaidAmount}

UPDATE t_payment_attempt
SET gateway_code = #{gatewayCode}
WHERE attempt_no = #{attemptNo}
  AND CHAR_LENGTH(attempt_no) = CHAR_LENGTH(#{attemptNo})
  AND CAST(attempt_no AS BINARY(256)) = CAST(#{attemptNo} AS BINARY(256))
  AND (gateway_code IS NULL OR CAST(gateway_code AS BINARY(256)) = CAST(#{gatewayCode} AS BINARY(256)))

UPDATE t_payment_route_record
SET ops_config_snapshot_version = #{snapshotVersion}
WHERE route_no = #{routeNo}
  AND CHAR_LENGTH(route_no) = CHAR_LENGTH(#{routeNo})
  AND CAST(route_no AS BINARY(256)) = CAST(#{routeNo} AS BINARY(256))

UPDATE t_payment_attempt
SET ops_config_snapshot_version = #{snapshotVersion}
WHERE attempt_no = #{attemptNo}
  AND CHAR_LENGTH(attempt_no) = CHAR_LENGTH(#{attemptNo})
  AND CAST(attempt_no AS BINARY(256)) = CAST(#{attemptNo} AS BINARY(256))
